/** @jsxImportSource kerfjs */
import { computed, mount, selector, signal } from 'kerfjs';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };
type Commit = (...args: unknown[]) => void;

const suggestions = ['Apricot', 'Blueberry', 'Cherry'];
const options = suggestions.map(value => ({ value, label: value }));
const Picker = Combobox as unknown as (props: {
  id: string;
  name: string;
  label: string;
  options: typeof options;
  suggestions: string[];
  onCommit: Commit;
}) => ReturnType<typeof Combobox>;
const wirePicker = wireComboboxes as unknown as (
  host: HTMLElement,
  handler: Commit & { onCommit: Commit }
) => unknown;

let nextPickerId = 0;

function readCommit(value: unknown): string | undefined {
  if (typeof value === 'string') return value;
  if (value instanceof CustomEvent) return readCommit(value.detail);
  if (value && typeof value === 'object' && !(value instanceof HTMLElement) &&
      'value' in value && typeof value.value === 'string') return value.value;
}

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void
) {
  const app = document.createElement('div');
  const inspector = document.createElement('div');
  const list = document.createElement('div');
  app.append(inspector, list);
  root.append(app);

  const counts = { incoming: signal(4), outgoing: signal(7) };
  const activeSource = signal<Source>('incoming');
  const badge = computed(() => `${counts[activeSource.value].value} crates`);
  const stopInspector = mount(inspector, () => (
    <>
      <output data-badge="" title={badge}>{badge}</output>
      <input data-note="" aria-label="Note" />
    </>
  ));

  const selectedId = signal<number | undefined>(undefined);
  const isSelected = selector(selectedId);

  function mountRow(record: RecordData) {
    const host = document.createElement('div');
    const label = signal(record.label);
    const selected = isSelected(record.id);
    const ariaSelected = computed(() => selected.value ? 'true' : 'false');
    const stop = mount(host, () => {
      mark('row');
      return (
        <div data-row={record.id} aria-selected={ariaSelected}>
          <span>{label}</span>
          <input aria-label={`Edit record ${record.id}`} />
        </div>
      );
    });
    return { host, label, stop };
  }

  const rows = new Map<number, ReturnType<typeof mountRow>>();
  let order: number[] = [];

  function placeRows() {
    const focused = document.activeElement;
    let next: HTMLElement | null = null;
    for (let index = order.length - 1; index >= 0; index--) {
      const { host } = rows.get(order[index])!;
      if (!host.contains(focused) &&
          (host.parentNode !== list || host.nextSibling !== next)) {
        list.insertBefore(host, next);
      }
      next = host;
    }
  }

  function replaceRecords(records: RecordData[]) {
    const nextOrder = records.map(record => record.id);
    const retained = new Set(nextOrder);
    for (const [id, row] of rows) {
      if (retained.has(id)) continue;
      row.stop();
      row.host.remove();
      rows.delete(id);
    }
    for (const record of records) {
      const row = rows.get(record.id);
      if (row) row.label.value = record.label;
      else rows.set(record.id, mountRow(record));
    }
    order = nextOrder;
    placeRows();
  }

  replaceRecords([
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' }
  ]);

  let disposed = false;
  let stopPicker: (() => void) | undefined;

  function close() {
    const stop = stopPicker;
    stopPicker = undefined;
    stop?.();
  }

  function open() {
    if (disposed || stopPicker) return;
    const host = document.createElement('div');
    const id = `study-fruit-${++nextPickerId}`;
    app.append(host);
    let active = true;
    let committing = false;

    function commit(...args: unknown[]) {
      if (!active || committing) return;
      const value = args.map(readCommit).find(candidate => candidate !== undefined);
      if (value === undefined || !value.trim()) return;
      committing = true;
      queueMicrotask(() => { committing = false; });
      const input = host.querySelector('input');
      if (input) input.value = '';
      onCommit(value);
    }

    const unmount = mount(host, () => (
      <Picker id={id} name="Fruit" label="Fruit" options={options}
        suggestions={suggestions} onCommit={commit} />
    ));
    const unwire = wirePicker(host, Object.assign(commit, { onCommit: commit }));
    stopPicker = () => {
      active = false;
      if (typeof unwire === 'function') unwire();
      unmount();
      host.remove();
    };
  }

  return {
    count(source: Source, value: number) {
      if (!disposed) counts[source].value = value;
    },
    mode(source: Source) {
      if (!disposed) activeSource.value = source;
    },
    select(id: number) {
      if (!disposed) selectedId.value = id;
    },
    refetch(records: RecordData[]) {
      if (!disposed) replaceRecords(records);
    },
    swap() {
      if (disposed || order.length < 2) return;
      [order[0], order[1]] = [order[1], order[0]];
      placeRows();
    },
    open,
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      for (const row of rows.values()) row.stop();
      rows.clear();
      order = [];
      stopInspector();
      app.remove();
    }
  };
}
